tasks.initialCode:
function shapeSig(o) { return Object.keys(o).join(','); }
function distinct(factory, inputs) {
  const seen = new Set();
  for (const inp of inputs) seen.add(shapeSig(factory(inp)));
  return seen.size;
}

const inputs = [
  { type: 'a', x: 0, y: 0 },
  { type: 'b', x: 1, y: 1, parent: 1 },
  { type: 'c', x: 2, y: 2, style: 's' },
  { type: 'd', x: 3, y: 3, parent: 1, style: 's' },
  { type: 'e', x: 4, y: 4, children: [] },
  { type: 'f', x: 5, y: 5, parent: 1, style: 's', children: [] },
];

// CONDITIONAL: fields appear only when present -> several shapes.
function conditional(input) {
  const n = {};
  n.type = input.type;
  if (input.parent) n.parent = input.parent;
  n.x = input.x;
  n.y = input.y;
  if (input.style) n.style = input.style;
  if (input.children) n.children = input.children;
  return n;
}

// FIXED SCHEMA: every field always present, fixed order -> one shape.
function fixedSchema(input) {
  return {
    type: input.type,
    parent: input.parent ?? null,
    x: input.x,
    y: input.y,
    style: input.style ?? null,
    children: input.children ?? null,
  };
}

const cond = distinct(conditional, inputs);
const fixed = distinct(fixedSchema, inputs);
console.log('conditional=' + cond + ' fixedSchema=' + fixed);

